-- Read-only catalog snapshot for the reviewed IDS objects; never selects application records.
SELECT jsonb_build_object(
 'tables', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','gk_private') AND c.relkind IN ('r','p')),'[]'::jsonb),
 'columns', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'collation',co.collname,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY n.nspname,c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum LEFT JOIN pg_collation co ON co.oid=a.attcollation WHERE n.nspname IN ('public','gk_private') AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped),'[]'::jsonb),
 'constraints', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'deferrable',k.condeferrable,'initially_deferred',k.condeferred,'definition',pg_get_constraintdef(k.oid,true)) ORDER BY n.nspname,c.relname,k.conname) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','gk_private')),'[]'::jsonb),
 'indexes', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',ic.relname,'unique',i.indisunique,'primary',i.indisprimary,'valid',i.indisvalid,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY n.nspname,c.relname,ic.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','gk_private')),'[]'::jsonb),
 'triggers', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'deferrable',t.tgdeferrable,'initially_deferred',t.tginitdeferred,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY n.nspname,c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','gk_private') AND NOT t.tgisinternal),'[]'::jsonb),
 'policies', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'with_check',with_check) ORDER BY schemaname,tablename,policyname) FROM pg_policies WHERE schemaname IN ('public','gk_private')),'[]'::jsonb),
 'functions', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'configuration',p.proconfig,'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='gk_private' OR (n.nspname='public' AND p.proname IN ('gk_register_member','gk_manage_membership'))),'[]'::jsonb),
 'table_privileges', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'role',r.rolname,'privilege',v.privilege,'allowed',has_table_privilege(r.oid,c.oid,v.privilege)) ORDER BY n.nspname,c.relname,r.rolname,v.privilege) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (SELECT oid,rolname FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) r CROSS JOIN (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) v(privilege) WHERE n.nspname IN ('public','gk_private') AND c.relkind IN ('r','p')),'[]'::jsonb),
 'function_privileges', COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'role',r.rolname,'execute',has_function_privilege(r.oid,p.oid,'EXECUTE')) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),r.rolname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN (SELECT oid,rolname FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) r WHERE n.nspname='gk_private' OR (n.nspname='public' AND p.proname IN ('gk_register_member','gk_manage_membership'))),'[]'::jsonb)
) AS catalog;
